/* A device-local profile preview, ready to connect to accounts later. */
(function(){
 const key='folio-profile-v1';
 const image=value=>{if(typeof value!=='string')return '';if(/^data:image\/(png|jpeg|webp|gif);base64,[a-z0-9+/=]+$/i.test(value))return value;try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password?u.href:'';}catch{return '';}};
 function load(){try{const p=JSON.parse(localStorage.getItem(key)||'{}');return {name:String(p.name||'Your profile').slice(0,40),bio:String(p.bio||'').slice(0,240),avatar:image(p.avatar),background:image(p.background),showcase:Array.isArray(p.showcase)?p.showcase.filter(id=>typeof id==='string').slice(0,4):null};}catch{return {name:'Your profile',bio:'',avatar:'',background:'',showcase:null};}}
 const page=document.createElement('section');page.id='profile-page';page.hidden=true;document.querySelector('main').append(page);
 function paint(){
  const p=load(),selected=p.showcase===null?items.filter(x=>x.favorite).slice(0,4):p.showcase.map(id=>items.find(x=>x.id===id)).filter(Boolean);
  const art=x=>image(x.coverImage||x.coverUrl||(x.metadata?imageFor(x.metadata):''));
  page.innerHTML=`<div class="profile-panel"><div class="profile-banner">${p.background?`<img src="${esc(p.background)}" alt="Profile background">`:'<span aria-hidden="true"></span>'}</div><div class="profile-identity"><div class="profile-avatar">${p.avatar?`<img src="${esc(p.avatar)}" alt="${esc(p.name)}’s profile picture">`:`<span aria-hidden="true">${esc(p.name.slice(0,1).toUpperCase())}</span>`}</div><div><small>MY PROFILE</small><h1>${esc(p.name)}</h1>${p.bio?`<p>${esc(p.bio)}</p>`:'<p class="muted">A little space for your favorite worlds.</p>'}</div><button type="button" class="secondary" id="profile-edit">Edit profile</button></div></div><section class="profile-showcase"><div class="section-heading"><h2>Showcase</h2><small>${selected.length} / 4 titles</small></div><div class="profile-shelf">${selected.map(x=>`<button type="button" data-profile-title="${esc(x.id)}" aria-label="Open ${esc(x.title)}">${art(x)?`<img src="${esc(art(x))}" alt="" loading="lazy">`:'<span class="profile-cover-placeholder" aria-hidden="true">▥</span>'}<strong>${esc(x.title)}</strong><small>${esc(x.type)}</small></button>`).join('')||'<p class="muted">Choose a few library titles to make this space yours.</p>'}</div></section><section class="profile-editor" hidden><h2>Edit profile</h2><form id="profile-form"><label>Display name<input name="name" maxlength="40" required value="${esc(p.name)}"></label><label>About you<textarea name="bio" maxlength="240" rows="3">${esc(p.bio)}</textarea></label>${['avatar','background'].map(type=>`<fieldset><legend>${type==='avatar'?'Profile picture':'Background artwork'}</legend><label>Image URL<input type="url" name="${type}" placeholder="https://…" value="${esc(p[type].startsWith('data:')?'':p[type])}"></label><div class="profile-image-tools"><label class="secondary">Upload image<input type="file" data-profile-upload="${type}" accept="image/png,image/jpeg,image/webp,image/gif"></label><button type="button" class="text-button" data-profile-remove="${type}">Remove image</button></div></fieldset>`).join('')}<fieldset class="profile-title-picker"><legend>Showcase · choose up to 4</legend>${items.map(x=>`<label><input type="checkbox" name="showcase" value="${esc(x.id)}" ${selected.some(s=>s.id===x.id)?'checked':''}>${esc(x.title)}</label>`).join('')||'<p>Add titles to your library first.</p>'}</fieldset><p id="profile-save-status" role="status"></p><div class="actions"><button type="button" class="secondary" id="profile-cancel">Cancel</button><button type="submit" class="primary">Save profile</button></div></form></section><p class="profile-local-note">Saved on this device.</p>`;
  page.querySelector('#profile-edit').onclick=()=>{page.querySelector('.profile-editor').hidden=false;page.querySelector('[name=name]').focus();};page.querySelector('#profile-cancel').onclick=()=>{page.querySelector('.profile-editor').hidden=true;page.querySelector('#profile-edit').focus();};
  page.querySelectorAll('[data-profile-title]').forEach(b=>b.onclick=()=>openOwnedDetail(b.dataset.profileTitle));
  page.querySelectorAll('img').forEach(img=>img.onerror=()=>img.hidden=true);
  const form=page.querySelector('form'),status=page.querySelector('#profile-save-status'),draft={...p};
  page.querySelectorAll('[data-profile-upload]').forEach(input=>input.onchange=()=>{const file=input.files[0];if(!file)return;if(file.size>2000000||!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type)){status.textContent='Choose a PNG, JPEG, WebP or GIF under 2 MB.';return;}const reader=new FileReader();reader.onload=()=>{draft[input.dataset.profileUpload]=reader.result;form.elements[input.dataset.profileUpload].value='';status.textContent='Image ready. Save profile to apply it.';};reader.readAsDataURL(file);});
  page.querySelectorAll('[data-profile-remove]').forEach(b=>b.onclick=()=>{draft[b.dataset.profileRemove]='';form.elements[b.dataset.profileRemove].value='';status.textContent='Image removed. Save profile to apply it.';});
  form.onsubmit=e=>{e.preventDefault();const data=new FormData(form),ids=data.getAll('showcase');if(ids.length>4){status.textContent='Choose up to 4 showcase titles.';return;}for(const type of ['avatar','background']){const raw=data.get(type).trim();if(raw&&!image(raw)){status.textContent='Use a valid HTTPS image URL.';return;}draft[type]=raw?image(raw):draft[type];}Object.assign(draft,{name:data.get('name').trim()||'Your profile',bio:data.get('bio').trim(),showcase:ids});try{localStorage.setItem(key,JSON.stringify(draft));paint();page.querySelector('#profile-edit').focus();toast('Profile saved');}catch{status.textContent='Could not save. Try smaller images to free browser storage.';}};
 }
 const previous=render;render=function(){previous();const active=view==='profile';page.hidden=!active;if(active){document.querySelector('#library-page').hidden=true;document.querySelector('#home-page').hidden=true;document.querySelector('#discovery').hidden=true;document.querySelector('main>header>span').textContent='My space / Profile';paint();}};render();
})();
